        super().__init__()
        # SwiGLU: 2.67x ratio with gate+up to match 4x ReLU² param count
        hidden = int(2.67 * config.n_embd)
        hidden = ((hidden + 63) // 64) * 64  # round to 64 for GPU efficiency
        self.c_gate = nn.Linear(config.n_embd, hidden, bias=False)
        self.c_up = nn.Linear(config.n_embd, hidden, bias=False)
        self.c_proj = nn.Linear(hidden, config.n_embd, bias=False)

    def forward(self, x):
        return self.c_proj(F.silu(self.c_gate(x)) * self.c_up(x))

